create table if not exists tenant (  id varchar(64) primary key,  code varchar(64) not null unique,  name varchar(128) not null,  status varchar(32) not null default 'active',  created_at timestamptz not null default now(),  updated_at timestamptz not null default now());create table if not exists sys_user (  id varchar(64) primary key,  tenant_id varchar(64) not null references tenant(id),  username varchar(64) not null unique,  display_name varchar(128) not null,  email varchar(128),  password_hash varchar(255) not null,  status varchar(32) not null default 'active',  created_at timestamptz not null default now(),  updated_at timestamptz not null default now());create table if not exists sys_role (  id varchar(64) primary key,  code varchar(64) not null unique,  name varchar(128) not null,  created_at timestamptz not null default now());create table if not exists sys_permission (  id varchar(64) primary key,  code varchar(128) not null unique,  name varchar(128) not null,  created_at timestamptz not null default now());create table if not exists sys_user_role (  user_id varchar(64) not null references sys_user(id) on delete cascade,  role_id varchar(64) not null references sys_role(id) on delete cascade,  primary key(user_id, role_id));create table if not exists sys_role_permission (  role_id varchar(64) not null references sys_role(id) on delete cascade,  permission_id varchar(64) not null references sys_permission(id) on delete cascade,  primary key(role_id, permission_id));
